node --input-type=module -e '
import ajv8 from "ajv";
import ajv6 from "./node_modules/eslint/node_modules/ajv/lib/ajv.js";
const opts = {strict: false, validateFormats: false, format: false, allErrors: true, logger: false};
for (const [label, Ctor] of [["v8", ajv8], ["v6", ajv6]]) {
  const compiler = new Ctor(opts);
  let threw = false;
  try {
    compiler.compile({type: "bogus"});
  } catch (e) {
    threw = true;
    console.log(label, "threw on bogus type:", e.message);
  }
  if (!threw) throw new Error(label + " did NOT throw on bogus type!");
  const okUnknownKeyword = compiler.compile({type: "object", "x-custom": 123, properties: {loc: {type: "string", format: "email"}}, required: ["loc"]});
  console.log(label, "valid pass-through:", okUnknownKeyword({loc: "not-an-email", extra: 42}));
}
'

node --input-type=module -e '
import ajv8 from "ajv";
import ajv6 from "./node_modules/eslint/node_modules/ajv/lib/ajv.js";
const opts = {strict: false, validateFormats: false, format: false, allErrors: true, logger: false};
for (const [label, Ctor] of [["v8", ajv8], ["v6", ajv6]]) {
  let reads = 0;
  const schema = {
    type: "object",
    get properties() {
      reads += 1;
      return {city: {type: "string"}};
    },
    required: ["city"],
  };
  const compiler = new Ctor(opts);
  const fn = compiler.compile(schema);
  const readsAfterCompile = reads;
  fn({});
  fn({city: "Berlin"});
  console.log(label, {readsAfterCompile, readsAfterValidate: reads, sameCount: reads === readsAfterCompile && readsAfterCompile > 0});
}
'
